627→@@ -0,0 +1,146 @@
628→+package improve
629→+
630→+import "strings"
631→+
632→+// SessionSummaryData pairs a session identifier with its friction and learnings.
633→+// This is populated from the insightsdb cache.
634→+type SessionSummaryData struct {
635→+	CheckpointID string
636→+	Friction     []string
637→+	Learnings    []LearningEntry
638→+	OpenItems    []string
639→+}
640→+
641→+// LearningEntry represents a single learning from a session.
642→+type LearningEntry struct {
643→+	Scope   string // "repo", "workflow", "code"
644→+	Finding string
645→+	Path    string
646→+}
647→+
648→+// frictionThemeKeywords maps theme names to their detection keywords.
649→+// Order matters: first match wins.
650→+var frictionThemeKeywords = []struct {
651→+	theme    string
652→+	keywords []string
653→+}{
654→+	{"lint", []string{"lint", "golangci", "linter"}},
655→+	{"import", []string{"import"}},
656→+	{"compile", []string{"compile", "build error", "compilation"}},
657→+	{"format", []string{"format", "fmt", "gofmt"}},
658→+	{"test", []string{"test", "testing"}},
659→+	{"type", []string{"type assertion", "type error", "type mismatch", "type check"}},
660→+	{"permission", []string{"permission", "denied", "unauthorized"}},
661→+	{"timeout", []string{"timeout", "timed out"}},
662→+	{"retry", []string{"retry", "retrying"}},
663→+}
664→+
665→+// classifyFriction returns the theme keyword for a friction string,
666→+// or "other" if no known keyword matches.
667→+func classifyFriction(text string) string {
668→+	lower := strings.ToLower(text)
669→+	for _, entry := range frictionThemeKeywords {
670→+		for _, kw := range entry.keywords {
671→+			if strings.Contains(lower, kw) {
672→+				return entry.theme
673→+			}
674→+		}
675→+	}
676→+	return "other"
677→+}
678→+
679→+// frictionAccumulator accumulates friction examples and affected sessions per theme.
680→+type frictionAccumulator struct {
681→+	count    int
682→+	examples []string
683→+	sessions map[string]struct{} // deduplicated session IDs
684→+}
685→+
686→+// AnalyzePatterns extracts recurring patterns from session summary data.
687→+// This is the "index phase" — it works on data already in memory from SQLite.
688→+func AnalyzePatterns(summaries []SessionSummaryData) PatternAnalysis {
689→+	if len(summaries) == 0 {
690→+		return PatternAnalysis{}
691→+	}
692→+
693→+	// Accumulate friction by theme
694→+	byTheme := make(map[string]*frictionAccumulator)
695→+
696→+	for _, s := range summaries {
697→+		for _, f := range s.Friction {
698→+			theme := classifyFriction(f)
699→+			acc, ok := byTheme[theme]
700→+			if !ok {
701→+				acc = &frictionAccumulator{
702→+					sessions: make(map[string]struct{}),
703→+				}
704→+				byTheme[theme] = acc
705→+			}
706→+			acc.count++
707→+			acc.examples = append(acc.examples, f)
708→+			if s.CheckpointID != "" {
709→+				acc.sessions[s.CheckpointID] = struct{}{}
710→+			}
711→+		}
712→+	}
713→+
714→+	// Build repeated friction list (threshold: 2+ occurrences)
715→+	var repeated []FrictionPattern
716→+	for theme, acc := range byTheme {
717→+		if acc.count < 2 {
718→+			continue
719→+		}
720→+		sessions := make([]string, 0, len(acc.sessions))
721→+		for id := range acc.sessions {
722→+			sessions = append(sessions, id)
723→+		}
724→+		repeated = append(repeated, FrictionPattern{
725→+			Theme:            theme,
726→+			Count:            acc.count,
727→+			Examples:         acc.examples,
728→+			AffectedSessions: sessions,
729→+		})
730→+	}
731→+
732→+	// Deduplicate learnings by scope
733→+	repoSeen := make(map[string]struct{})
734→+	workflowSeen := make(map[string]struct{})
735→+	var repoLearnings, workflowLearnings []string
736→+
737→+	for _, s := range summaries {
738→+		for _, l := range s.Learnings {
739→+			switch l.Scope {
740→+			case "repo":
741→+				if _, seen := repoSeen[l.Finding]; !seen {
742→+					repoSeen[l.Finding] = struct{}{}
743→+					repoLearnings = append(repoLearnings, l.Finding)
744→+				}
745→+			case "workflow":
746→+				if _, seen := workflowSeen[l.Finding]; !seen {
747→+					workflowSeen[l.Finding] = struct{}{}
748→+					workflowLearnings = append(workflowLearnings, l.Finding)
749→+				}
750→+			}
751→+		}
752→+	}
753→+
754→+	// Deduplicate open items
755→+	openSeen := make(map[string]struct{})
756→+	var openItems []string
757→+	for _, s := range summaries {
758→+		for _, item := range s.OpenItems {
759→+			if _, seen := openSeen[item]; !seen {
760→+				openSeen[item] = struct{}{}
761→+				openItems = append(openItems, item)
762→+			}
763→+		}
764→+	}
765→+
766→+	return PatternAnalysis{
767→+		RepeatedFriction:  repeated,
768→+		RepoLearnings:     repoLearnings,
769→+		WorkflowLearnings: workflowLearnings,
770→+		OpenItems:         openItems,
771→+		SessionCount:      len(summaries),
772→+	}
773→+}
