138→// buildFrictionPatterns converts insightsdb friction themes to improve.FrictionPattern values.
139→func buildFrictionPatterns(themes []insightsdb.FrictionTheme) []improve.FrictionPattern {
140→	patterns := make([]improve.FrictionPattern, 0, len(themes))
141→	for _, t := range themes {
142→		patterns = append(patterns, improve.FrictionPattern{
143→			Theme:            t.Text,
144→			Count:            t.Count,
145→			AffectedSessions: t.Sessions,
146→		})
147→	}
148→	return patterns
149→}
150→
151→// attachTranscriptExcerpts fetches transcript excerpts for top friction themes and
152→// attaches them to the corresponding patterns in-place.
153→// Errors are non-fatal; unreadable sessions are silently skipped.
154→func attachTranscriptExcerpts(ctx context.Context, idb *insightsdb.InsightsDB, patterns []improve.FrictionPattern, _ string) error {
155→	repo, err := openRepository(ctx)
156→	if err != nil {
157→		return fmt.Errorf("open git repository: %w", err)
158→	}
159→	store := checkpoint.NewGitStore(repo)
160→
161→	// Limit to top 3 friction themes.
162→	limit := 3
163→	if len(patterns) < limit {
164→		limit = len(patterns)
165→	}
166→
167→	for i := range patterns[:limit] {
168→		cpIDs, queryErr := idb.QuerySessionsWithFriction(ctx, "%"+patterns[i].Theme+"%")
169→		if queryErr != nil {
170→			continue
171→		}
172→
173→		// Limit to top 2 sessions per theme.
174→		sessionLimit := 2
175→		if len(cpIDs) < sessionLimit {
176→			sessionLimit = len(cpIDs)
177→		}
178→
179→		var excerpts []string
180→		for _, cpIDStr := range cpIDs[:sessionLimit] {
181→			cpID, parseErr := checkpointid.NewCheckpointID(cpIDStr)
182→			if parseErr != nil {
183→				continue
184→			}
185→
186→			content, readErr := store.ReadSessionContent(ctx, cpID, 0)
187→			if readErr != nil {
188→				continue
189→			}
190→
191→			condensed, buildErr := summarize.BuildCondensedTranscriptFromBytes(content.Transcript, content.Metadata.Agent)
192→			if buildErr != nil || len(condensed) == 0 {
193→				continue
194→			}
195→
196→			formatted := summarize.FormatCondensedTranscript(summarize.Input{Transcript: condensed})
197→			excerpt := truncateString(formatted, 2000)
198→			if excerpt != "" {
199→				excerpts = append(excerpts, excerpt)
200→			}
201→		}
202→
203→		if len(excerpts) > 0 {
204→			patterns[i].TranscriptExcerpt = strings.Join(excerpts, "\n---\n")
205→		}
206→	}
207→
208→	return nil
209→}
210→
211→// applyExcerpts copies TranscriptExcerpt values from src patterns into dst patterns
212→// by matching on theme text.
213→func applyExcerpts(dst []improve.FrictionPattern, src []improve.FrictionPattern) {
214→	excerptByTheme := make(map[string]string, len(src))
215→	for _, p := range src {
216→		if p.TranscriptExcerpt != "" {
217→			excerptByTheme[p.Theme] = p.TranscriptExcerpt
218→		}
219→	}
220→	for i := range dst {
221→		if excerpt, ok := excerptByTheme[dst[i].Theme]; ok {
222→			dst[i].TranscriptExcerpt = excerpt
223→		}
224→	}
225→}
