 10→// SessionRow represents a single session for insertion into the cache.
 11→// This is the denormalized view used by the CLI — callers populate it
 12→// from checkpoint.CommittedMetadata.
 13→type SessionRow struct {
 14→	CheckpointID string
 15→	SessionID    string
 16→	SessionIndex int
 17→	Agent        string
 18→	Model        string
 19→	Branch       string
 20→	CreatedAt    time.Time
 21→	InputTokens  int
 22→	CacheTokens  int
 23→	OutputTokens int
 24→	TotalTokens  int
 25→	APICallCount int
 26→	DurationMs   int64
 27→	TurnCount    int
 28→	Intent       string
 29→	Outcome      string
 30→	AgentPct     float64
 31→	// Score fields (may be zero if not yet computed)
 32→	OverallScore   float64
 33→	ScoreTokenEff  float64
 34→	ScoreFirstPass float64
 35→	ScoreFriction  float64
 36→	ScoreFocus     float64
 37→	// Denormalized arrays
 38→	FilesTouched []string
 39→	Friction     []string
 40→	Learnings    []LearningRow
 41→}
 42→
 43→// LearningRow represents a single learning entry within a session.
 44→type LearningRow struct {
 45→	Scope   string // "repo", "workflow", "code"
 46→	Finding string
 47→	Path    string // only meaningful when Scope is "code"
 48→}
 49→
 50→// GetBranchTip returns the stored branch tip hash from cache_meta,
 51→// or an empty string if it has not been set yet.
 52→func (idb *InsightsDB) GetBranchTip(ctx context.Context) (string, error) {
 53→	var tip string
 54→	err := idb.db.QueryRowContext(ctx,
 55→		"SELECT value FROM cache_meta WHERE key = ?",
 56→		"branch_tip",
 57→	).Scan(&tip)
 58→	if err == sql.ErrNoRows {
 59→		return "", nil
 60→	}
 61→	if err != nil {
 62→		return "", fmt.Errorf("get branch tip: %w", err)
 63→	}
 64→	return tip, nil
 65→}
 66→
 67→// SetBranchTip stores the branch tip hash in cache_meta.
 68→// Overwrites any previously stored value.
 69→func (idb *InsightsDB) SetBranchTip(ctx context.Context, tip string) error {
 70→	_, err := idb.db.ExecContext(ctx,
 71→		"INSERT OR REPLACE INTO cache_meta (key, value) VALUES (?, ?)",
 72→		"branch_tip",
 73→		tip,
 74→	)
 75→	if err != nil {
 76→		return fmt.Errorf("set branch tip: %w", err)
 77→	}
 78→	return nil
 79→}
 80→
 81→// HasCheckpoint returns true if any session for the given checkpoint ID
 82→// is already present in the sessions table.
 83→func (idb *InsightsDB) HasCheckpoint(ctx context.Context, checkpointID string) (bool, error) {
 84→	var count int
 85→	err := idb.db.QueryRowContext(ctx,
 86→		"SELECT COUNT(*) FROM sessions WHERE checkpoint_id = ?",
 87→		checkpointID,
 88→	).Scan(&count)
 89→	if err != nil {
 90→		return false, fmt.Errorf("check checkpoint existence: %w", err)
 91→	}
 92→	return count > 0, nil
 93→}
