 95→// InsertSession inserts a session and all its denormalized data into the cache.
 96→// The insert is performed inside a single transaction so the cache remains
 97→// consistent even if the caller is interrupted mid-insert.
 98→func (idb *InsightsDB) InsertSession(ctx context.Context, row SessionRow) error {
 99→	tx, err := idb.db.BeginTx(ctx, nil)
100→	if err != nil {
101→		return fmt.Errorf("begin transaction: %w", err)
102→	}
103→	defer func() {
104→		if err != nil {
105→			_ = tx.Rollback() //nolint:errcheck // Rollback after failed tx; error is irrelevant
106→		}
107→	}()
108→
109→	if err = insertSessionRow(ctx, tx, row); err != nil {
110→		return err
111→	}
112→	if err = insertFilesTouched(ctx, tx, row); err != nil {
113→		return err
114→	}
115→	if err = insertFriction(ctx, tx, row); err != nil {
116→		return err
117→	}
118→	if err = insertLearnings(ctx, tx, row); err != nil {
119→		return err
120→	}
121→
122→	if err = tx.Commit(); err != nil {
123→		return fmt.Errorf("commit transaction: %w", err)
124→	}
125→	return nil
126→}
