128→func insertSessionRow(ctx context.Context, tx *sql.Tx, row SessionRow) error {
129→	_, err := tx.ExecContext(ctx, `
130→		INSERT INTO sessions (
131→			checkpoint_id, session_id, session_index,
132→			agent, model, branch, created_at,
133→			input_tokens, cache_tokens, output_tokens, total_tokens,
134→			api_call_count, duration_ms, turn_count,
135→			intent, outcome, agent_percentage,
136→			overall_score, score_token_efficiency, score_first_pass,
137→			score_friction, score_focus
138→		) VALUES (
139→			?, ?, ?,
140→			?, ?, ?, ?,
141→			?, ?, ?, ?,
142→			?, ?, ?,
143→			?, ?, ?,
144→			?, ?, ?,
145→			?, ?
146→		)`,
147→		row.CheckpointID, row.SessionID, row.SessionIndex,
148→		nullableString(row.Agent), nullableString(row.Model), nullableString(row.Branch),
149→		row.CreatedAt.UTC().Format(time.RFC3339),
150→		row.InputTokens, row.CacheTokens, row.OutputTokens, row.TotalTokens,
151→		row.APICallCount, row.DurationMs, row.TurnCount,
152→		nullableString(row.Intent), nullableString(row.Outcome), row.AgentPct,
153→		nullableFloat(row.OverallScore), nullableFloat(row.ScoreTokenEff),
154→		nullableFloat(row.ScoreFirstPass), nullableFloat(row.ScoreFriction),
155→		nullableFloat(row.ScoreFocus),
156→	)
157→	if err != nil {
158→		return fmt.Errorf("insert session row: %w", err)
159→	}
160→	return nil
161→}
