163→func insertFilesTouched(ctx context.Context, tx *sql.Tx, row SessionRow) error {
164→	for _, f := range row.FilesTouched {
165→		if _, err := tx.ExecContext(ctx,
166→			"INSERT INTO files_touched (checkpoint_id, session_index, file_path) VALUES (?, ?, ?)",
167→			row.CheckpointID, row.SessionIndex, f,
168→		); err != nil {
169→			return fmt.Errorf("insert files_touched: %w", err)
170→		}
171→	}
172→	return nil
173→}
