175→func insertFriction(ctx context.Context, tx *sql.Tx, row SessionRow) error {
176→	for _, f := range row.Friction {
177→		if _, err := tx.ExecContext(ctx,
178→			"INSERT INTO friction (checkpoint_id, session_index, text) VALUES (?, ?, ?)",
179→			row.CheckpointID, row.SessionIndex, f,
180→		); err != nil {
181→			return fmt.Errorf("insert friction: %w", err)
182→		}
183→	}
184→	return nil
185→}
186→
187→func insertLearnings(ctx context.Context, tx *sql.Tx, row SessionRow) error {
188→	for _, l := range row.Learnings {
189→		if _, err := tx.ExecContext(ctx,
190→			"INSERT INTO learnings (checkpoint_id, session_index, scope, finding, path) VALUES (?, ?, ?, ?, ?)",
191→			row.CheckpointID, row.SessionIndex, l.Scope, l.Finding, nullableString(l.Path),
192→		); err != nil {
193→			return fmt.Errorf("insert learnings: %w", err)
194→		}
195→	}
196→	return nil
197→}
