 11→// FrictionTheme groups recurring friction entries by their text content.
 12→type FrictionTheme struct {
 13→	Text     string   `json:"text"`
 14→	Count    int      `json:"count"`
 15→	Sessions []string `json:"sessions"` // checkpoint IDs where this friction occurred
 16→}
 17→
 18→// QueryLastNSessions returns the most recent N sessions ordered by created_at DESC.
 19→// Denormalized fields (FilesTouched, Friction, Learnings) are populated.
 20→func (idb *InsightsDB) QueryLastNSessions(ctx context.Context, n int) ([]SessionRow, error) {
 21→	return idb.querySessions(ctx,
 22→		"SELECT "+sessionColumns+" FROM sessions ORDER BY created_at DESC LIMIT ?",
 23→		n,
 24→	)
 25→}
 26→
 27→// QueryByAgent returns sessions filtered by agent name, most recent first.
 28→func (idb *InsightsDB) QueryByAgent(ctx context.Context, agent string, limit int) ([]SessionRow, error) {
 29→	return idb.querySessions(ctx,
 30→		"SELECT "+sessionColumns+" FROM sessions WHERE agent = ? ORDER BY created_at DESC LIMIT ?",
 31→		agent, limit,
 32→	)
 33→}
