 35→// SessionCount returns the total number of cached sessions.
 36→func (idb *InsightsDB) SessionCount(ctx context.Context) (int, error) {
 37→	var count int
 38→	if err := idb.db.QueryRowContext(ctx, "SELECT COUNT(*) FROM sessions").Scan(&count); err != nil {
 39→		return 0, fmt.Errorf("session count: %w", err)
 40→	}
 41→	return count, nil
 42→}
 43→
 44→// QueryRecurringFriction returns friction themes occurring at least minCount times,
 45→// ordered by count descending.
 46→func (idb *InsightsDB) QueryRecurringFriction(ctx context.Context, minCount int) ([]FrictionTheme, error) {
 47→	rows, err := idb.db.QueryContext(ctx, `
 48→		SELECT text, COUNT(*) AS cnt, GROUP_CONCAT(DISTINCT checkpoint_id) AS sessions
 49→		FROM friction
 50→		GROUP BY text
 51→		HAVING cnt >= ?
 52→		ORDER BY cnt DESC
 53→	`, minCount)
 54→	if err != nil {
 55→		return nil, fmt.Errorf("query recurring friction: %w", err)
 56→	}
 57→	defer rows.Close()
 58→
 59→	var themes []FrictionTheme
 60→	for rows.Next() {
 61→		var theme FrictionTheme
 62→		var sessionsCSV string
 63→		if err = rows.Scan(&theme.Text, &theme.Count, &sessionsCSV); err != nil {
 64→			return nil, fmt.Errorf("scan friction theme: %w", err)
 65→		}
 66→		theme.Sessions = splitCSV(sessionsCSV)
 67→		themes = append(themes, theme)
 68→	}
 69→	if err = rows.Err(); err != nil {
 70→		return nil, fmt.Errorf("iterate friction themes: %w", err)
 71→	}
 72→	return themes, nil
 73→}
 74→
 75→// QuerySessionsWithFriction returns checkpoint IDs of sessions containing
 76→// friction matching the given SQL LIKE pattern (e.g., "%tool call failed%").
 77→func (idb *InsightsDB) QuerySessionsWithFriction(ctx context.Context, pattern string) ([]string, error) {
 78→	rows, err := idb.db.QueryContext(ctx,
 79→		"SELECT DISTINCT checkpoint_id FROM friction WHERE text LIKE ?",
 80→		pattern,
 81→	)
 82→	if err != nil {
 83→		return nil, fmt.Errorf("query sessions with friction: %w", err)
 84→	}
 85→	defer rows.Close()
 86→
 87→	var ids []string
 88→	for rows.Next() {
 89→		var id string
 90→		if err = rows.Scan(&id); err != nil {
 91→			return nil, fmt.Errorf("scan checkpoint id: %w", err)
 92→		}
 93→		ids = append(ids, id)
 94→	}
 95→	if err = rows.Err(); err != nil {
 96→		return nil, fmt.Errorf("iterate session friction: %w", err)
 97→	}
 98→	return ids, nil
 99→}
