101→// sessionColumns is the ordered column list for SELECT queries on the sessions table.
102→const sessionColumns = `
103→	checkpoint_id, session_id, session_index,
104→	agent, model, branch, created_at,
105→	input_tokens, cache_tokens, output_tokens, total_tokens,
106→	api_call_count, duration_ms, turn_count,
107→	intent, outcome, agent_percentage,
108→	overall_score, score_token_efficiency, score_first_pass,
109→	score_friction, score_focus`
110→
111→// querySessions executes a SELECT on sessions with the given args,
112→// then populates denormalized fields for each row.
113→func (idb *InsightsDB) querySessions(ctx context.Context, query string, args ...interface{}) ([]SessionRow, error) {
114→	rows, err := idb.db.QueryContext(ctx, query, args...)
115→	if err != nil {
116→		return nil, fmt.Errorf("query sessions: %w", err)
117→	}
118→	defer rows.Close()
119→
120→	var sessions []SessionRow
121→	for rows.Next() {
122→		row, err := scanSession(rows)
123→		if err != nil {
124→			return nil, err
125→		}
126→		sessions = append(sessions, row)
127→	}
128→	if err = rows.Err(); err != nil {
129→		return nil, fmt.Errorf("iterate sessions: %w", err)
130→	}
131→
132→	for i := range sessions {
133→		if err = idb.populateDenormalized(ctx, &sessions[i]); err != nil {
134→			return nil, err
135→		}
136→	}
137→	return sessions, nil
138→}
139→
140→// scanSession reads one row from the sessions table into a SessionRow.
141→func scanSession(rows *sql.Rows) (SessionRow, error) {
142→	var row SessionRow
143→	var createdAt string
144→	var agent, model, branch, intent, outcome sql.NullString
145→	var overallScore, tokenEff, firstPass, friction, focus sql.NullFloat64
146→
147→	err := rows.Scan(
148→		&row.CheckpointID, &row.SessionID, &row.SessionIndex,
149→		&agent, &model, &branch, &createdAt,
150→		&row.InputTokens, &row.CacheTokens, &row.OutputTokens, &row.TotalTokens,
151→		&row.APICallCount, &row.DurationMs, &row.TurnCount,
152→		&intent, &outcome, &row.AgentPct,
153→		&overallScore, &tokenEff, &firstPass,
154→		&friction, &focus,
155→	)
156→	if err != nil {
157→		return row, fmt.Errorf("scan session row: %w", err)
158→	}
159→
160→	row.Agent = agent.String
161→	row.Model = model.String
162→	row.Branch = branch.String
163→	row.Intent = intent.String
164→	row.Outcome = outcome.String
165→	row.OverallScore = overallScore.Float64
166→	row.ScoreTokenEff = tokenEff.Float64
167→	row.ScoreFirstPass = firstPass.Float64
168→	row.ScoreFriction = friction.Float64
169→	row.ScoreFocus = focus.Float64
170→
171→	t, err := time.Parse(time.RFC3339, createdAt)
172→	if err != nil {
173→		return row, fmt.Errorf("parse created_at %q: %w", createdAt, err)
174→	}
175→	row.CreatedAt = t
176→	return row, nil
177→}
